-- Database: MariaDB / ERPNext v16
-- Dataset: Simulated business transactions
-- ============================================================

-- Purpose:
-- Calculate total sales revenue generated by each product.
-- Identify the products contributing most to business revenue.
-- Include only submitted sales invoices.

SELECT

    sii.item_name AS product,

    ROUND(
        SUM(sii.base_net_amount),
        2
    ) AS revenue

FROM `tabSales Invoice Item` AS sii

INNER JOIN `tabSales Invoice` AS si
    ON sii.parent = si.name

WHERE si.company = 'TechStore Algeria'
    AND si.docstatus = 1
    AND si.posting_date BETWEEN '2026-01-01'
                            AND '2026-12-31'

GROUP BY
    sii.item_code,
    sii.item_name

ORDER BY
    revenue DESC;

-- ============================================================
-- Limitations:
-- Uses a fixed fiscal year and company name.
-- Revenue is calculated in the company's base currency.
-- Revenue excludes VAT and does not represent cash collected.
-- ============================================================
